/* ===========================================================================
 
  Name:            vnim_message_monitoring_periodic
 
  Description:     Function to log/clear message missing and node missing dtc
 
  Inputs:          void
 
  Returns:         none
 
  =========================================================================*/
void vnim_message_monitoring_periodic(void)
{
  unsigned8 idx;
  PRECONDITION_STS vnim_log_cond = PRECONDITION_FALSE;

  if(IS_NM_NODE_MONITORING_ON() == TRUE)
  {
    for(idx =0;idx<NUM_VNIM_MESSAGES ;idx++)
    {
        vnim_log_cond = vnim_precondition_check(idx,VNIM_FAULT_CHECK);    
        if(vnim_content_error_sts[idx]!=0x00)
        {
        MsgDtcFlag[idx]=1u;
        }
        if((MsgDtcFlag[idx] != MsgDtcFlag_previous[idx]) && (vnim_log_cond != PRECONDITION_FALSE)) /* change in the state of DTC */
        {
          if(MsgDtcFlag[idx] == 1) /* DLC error has occured */
          {
            if((idx ==VNIM_VCU5_500_MSGID)&& (Suppress_VINDTC_Logging == TRUE)) 
            {                                                                       
                /* Do Nothing */	                                                                    
            }                                                                       
            else                                                                    
            {  
              if(vnim_msg_node_list[idx] == 0xFF)
              {
                /*Unlog DTC Interface*/
                vnim_msg_content_fault(idx);
              }
              else
              {
                vnim_node_msg_content_fault(vnim_msg_node_list[idx]);
              }
            }                                                                    
          }
          else if(MsgDtcFlag[idx] == 0)/* DLC error is cleared */
          {
              if(vnim_msg_node_list[idx] == 0xFF)
              {
                /*Unlog DTC Interface*/
                vnim_msg_content_gain(idx);
              }
              else
              {
                vnim_node_msg_content_gain(vnim_msg_node_list[idx]);
              }
          }
          else
          {
            /* Do Nothing */
          }
        }
        else
        {
          /* Do Nothing */
        }  
        MsgDtcFlag_previous[idx] = MsgDtcFlag[idx];
    }
  }
  else
  {
    /* Do nothing */
  }

  for(idx=0;idx<NUM_VNIM_MESSAGES ;idx++)
  {
      vnim_log_cond = vnim_precondition_check(idx,VNIM_FAULT_CHECK);
      if (vnim_log_cond != PRECONDITION_FALSE)
      {
          if(vnim_msg_missing_heal_timecnt[idx]!= (unsigned32)0)
          {
            vnim_msg_missing_heal_timecnt[idx]--;
            if(vnim_msg_missing_heal_timecnt[idx] ==(unsigned32) 0)
            {
              if (vnim_msg_healing_msgcnt[idx] ==(unsigned32)0)
              {
                vnim_msg_missing [vnim_msg_byte_position[idx]] &= ((unsigned8)~(vnim_msg_bit_mask[idx]));
                if(vnim_msg_node_list[idx] == 0xFF)
                {
                  /*Unlog DTC Interface*/
                  vnim_message_gain (idx);
                }
                else
                {
                  vnim_node_gain(vnim_msg_node_list[idx]);
                }
              }
              else
              {
                 vnim_msg_missing[vnim_msg_byte_position[idx]] |= vnim_msg_bit_mask[idx];
              }
            }
          }
    }
  }
}



/* ===========================================================================
   Received Interaction Layer Signal Indication Callbacks 
  =========================================================================*/

void VnimIlRx_ACC1_500_MsgIndication( void )
{
   CAN_UINT8  msg_changed =FALSE;
   CAN_UINT8  ret= FALSE;
   PRECONDITION_STS vnim_notify_sts = PRECONDITION_FALSE;
   vnim_notify_sts = vnim_precondition_check(VNIM_ACC1_500_MSGID,VNIM_MSG_IND_NOTIFY);
   if (IS_NM_NODE_MONITORING_ON() == TRUE)
   {
       ret = vnim_start_error_healing(VNIM_ACC1_500_MSGID,VNIM_ACC1_500_MESSAGE,NODE_ABSENT_HEAL_COUNT);
       if( ret == TRUE)
       {
           ILSet_ACC_INPUT_DC_CURRENT_DataChanged();
           ILSet_ACC_COM_FAULT_DataChanged();
           ILSet_ACC_OVERVOLTAGE_FAULT_DataChanged();
           ILSet_ACC_CONTROLLER_OVERHEAT_FAULT_DataChanged();
           ILSet_ACC_UNDERVOLTAGE_FAULT_DataChanged();
           ILSet_ACC_OVERCURRENT_FAULT_DataChanged();
           ILSet_STS_ACC_DataChanged();
           ILSet_ACC_MOTOR_OVERHEAT_FAULT_DataChanged();
       }
   }
   else
   {
     /*Do Nothing */
   }

   if(vnim_notify_sts!= PRECONDITION_FALSE)
   {
       if(((IS_NM_NODE_MONITORING_ON() == TRUE) &&
          (IS_ACC_NODE_MISSING() == FALSE) &&
          (IS_ACC_DLC_FAULT(VNIM_ACC1_500_MSGID) == FALSE)) ||
          (IS_NM_NODE_MONITORING_ON() != TRUE))
      {
          if(ILGet_ACC_INPUT_DC_CURRENT_DataChanged() != FALSE)
          {
              msg_changed = TRUE;
              ILClr_ACC_INPUT_DC_CURRENT_DataChanged();
          }

          if(ILGet_ACC_COM_FAULT_DataChanged() != FALSE)
          {
              msg_changed = TRUE;
              ILClr_ACC_COM_FAULT_DataChanged();
          }

          if(ILGet_ACC_OVERVOLTAGE_FAULT_DataChanged() != FALSE)
          {
              msg_changed = TRUE;
              ILClr_ACC_OVERVOLTAGE_FAULT_DataChanged();
          }

          if(ILGet_ACC_CONTROLLER_OVERHEAT_FAULT_DataChanged() != FALSE)
          {
              msg_changed = TRUE;
              ILClr_ACC_CONTROLLER_OVERHEAT_FAULT_DataChanged();
          }

          if(ILGet_ACC_UNDERVOLTAGE_FAULT_DataChanged() != FALSE)
          {
              msg_changed = TRUE;
              ILClr_ACC_UNDERVOLTAGE_FAULT_DataChanged();
          }

          if(ILGet_ACC_OVERCURRENT_FAULT_DataChanged() != FALSE)
          {
              msg_changed = TRUE;
              ILClr_ACC_OVERCURRENT_FAULT_DataChanged();
          }

          if(ILGet_STS_ACC_DataChanged() != FALSE)
          {
              msg_changed = TRUE;
              ILClr_STS_ACC_DataChanged();
          }

          if(ILGet_ACC_MOTOR_OVERHEAT_FAULT_DataChanged() != FALSE)
          {
              msg_changed = TRUE;
              ILClr_ACC_MOTOR_OVERHEAT_FAULT_DataChanged();
          }

          if((msg_changed == TRUE) && (ACC_node_cfg_st == CF_OPT_ACC_PRSNT))
          {
              #if (vnim_notify_used(VNRCL_ACC1_500_MSGID) == YES)
                os_notify(VNRCL_ACC1_500_MSGID,0, NULL );
              #endif
          }

      }

   }

APP_ACC1_500_INDICATION();
}

